import java.util.*;
import java.io.*;

public class CFA {
    BufferedReader br;
    PrintWriter out;
    StringTokenizer st;
    boolean eof;
    private static final long MOD = 998244353L;
    private static final int[] dx = {0, -1, 0, 1};
    private static final int[] dy = {1, 0, -1, 0};
    private static final String yes = "Yes";
    private static final String no = "No";

    class Point {
        int x;
        int y;
        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        if (n > m) {
            int tmp = n;
            n = m;
            m = tmp;
        }

        if (n == 1) {
            m--;
            int[] left = {0, 0, 0, 2, 4, 6};
            long res = m / 6 * 6 + left[m % 6];
            outln(res);
            return;
        }
        else if (n == 2) {
            if (m < 20) {
                outln(bruteforce(n, m));
            }
            else {
                outln(1L * n * m);
            }
            return;
        }
        else if (n == 3) {
            if (m < 20) {
                outln(bruteforce(n, m));
            }
            else {
                long res = 1L * n * m;
                if (res % 2 != 0) {
                    res--;
                }
                outln(res);
            }
            return;
        }

        if (1L * n * m < 1000) {
            outln(bruteforce(n, m));
            return;
        }
        long res = 1L * n * m;
        if (res % 2 != 0) {
            res--;
        }
        outln(res);
    }

    int bruteforce(int n, int m) {
        List<Point> even = new ArrayList<>();
        List<Point> odd = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int sum = i + j;
                if (sum % 2 == 0) {
                    even.add(new Point(i, j));
                }
                else {
                    odd.add(new Point(i, j));
                }
            }
        }

        boolean[][] match = new boolean[even.size()][odd.size()];
        for (int i = 0; i < match.length; i++) {
            for (int j = 0; j < match[0].length; j++) {
                int d = Math.abs(even.get(i).x - odd.get(j).x) + Math.abs(even.get(i).y - odd.get(j).y);
                if (d == 3) {
                    match[i][j] = true;
                }
            }
        }

        return 2 * maxMatching(match);
    }

    int maxMatching(boolean[][] graph) {
        int n1 = graph.length;
        int n2 = n1 == 0 ? 0 : graph[0].length;
        int[] matching = new int[n2];
        Arrays.fill(matching, -1);
        int matches = 0;
        for (int u = 0; u < n1; u++)
            if (findPath(graph, u, matching, new boolean[n1]))
                ++matches;
        return matches;
    }

    boolean findPath(boolean[][] graph, int u1, int[] matching, boolean[] vis) {
        vis[u1] = true;
        for (int v = 0; v < matching.length; ++v) {
            int u2 = matching[v];
            if (graph[u1][v] && (u2 == -1 || !vis[u2] && findPath(graph, u2, matching, vis))) {
                matching[v] = u1;
                return true;
            }
        }
        return false;
    }

    void shuffle(int[] a) {
        int n = a.length;
        for(int i = 0; i < n; i++) {
            int r = i + (int) (Math.random() * (n - i));
            int tmp = a[i];
            a[i] = a[r];
            a[r] = tmp;
        }
    }

    long gcd(long a, long b) {
        while(a != 0 && b != 0) {
            long c = b;
            b = a % b;
            a = c;
        }
        return a + b;
    }

    private void outln(Object o) {
        out.println(o);
    }
    private void out(Object o) {
        out.print(o);
    }
    private void formatPrint(double val) {
        System.out.format("%.9f%n", val);
    }
    public CFA() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }
    public static void main(String[] args) throws IOException {
        new CFA();
    }

    public long[] nextLongArr(int n) throws IOException{
        long[] res = new long[n];
        for(int i = 0; i < n; i++)
            res[i] = nextLong();
        return res;
    }
    public int[] nextIntArr(int n) throws IOException {
        int[] res = new int[n];
        for(int i = 0; i < n; i++)
            res[i] = nextInt();
        return res;
    }
    public String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                eof = true;
                return null;
            }
        }
        return st.nextToken();
    }
    public String nextString() {
        try {
            return br.readLine();
        } catch (IOException e) {
            eof = true;
            return null;
        }
    }
    public int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }
    public long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }
    public double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }
}
